plugins {
    alias(libs.plugins.android.library)
}

android {
    namespace = "com.phonxiety.bridge.device"
    compileSdk {
        version = release(37) { minorApiLevel = 1 }
    }

    defaultConfig {
        minSdk {
            version = release(34)
        }
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    // Kotlin sources live under src/main/java and src/main/kotlin; the
    // uniffi bindings generated by `mise run phone:iroh` stay in src/iroh.
    sourceSets.named("main") {
        kotlin.srcDir("src/iroh/kotlin")
    }

    lint {
        warningsAsErrors = true
        abortOnError = true
    }

    testOptions {
        // android.util.Log and friends are stubs on the JVM; return defaults
        // instead of throwing so the net/ code stays unit-testable.
        unitTests {
            isReturnDefaultValues = true
        }
    }
}

dependencies {
    implementation(libs.okhttp)

    // iroh Android bindings (generated by `mise run phone:iroh`).
    // The uniffi-generated Kotlin calls into libiroh_ffi.so through JNA. On
    // Android the @aar variant is required: it bundles libjnidispatch.so per
    // ABI, which JNA loads with System.loadLibrary() from the APK.
    //noinspection UseTomlInstead -- the catalog cannot express the @aar type,
    // and the JVM jar carries no libjnidispatch.so.
    implementation("net.java.dev.jna:jna:${libs.versions.jna.get()}@aar")
    // The generated bindings expose suspend functions.
    implementation(libs.kotlinx.coroutines.android)

    testImplementation(libs.junit)
    testImplementation(libs.kotlinx.coroutines.test)
    testImplementation(libs.turbine)
    testImplementation(libs.robolectric)
}
